/* Connected care workflows. All displayed health records come from the secured API. */
Object.assign(S,{admissions:[],administrations:[],growth:[],episodes:[],notifications:{items:[]},family:{members:[]},trends:{groups:[]},review:null});
NAV.push(['growth','Growth'],['episodes','Illness history'],['notifications','Notifications'],['family','Family access'],['settings','Settings']);
const paths={today:'M3 10 12 3l9 7v10H3z M9 20v-7h6v7',documents:'M6 3h8l4 4v14H6z M14 3v5h5 M9 12h6 M9 16h6',medicines:'m8 4 12 12a5 5 0 0 1-7 7L1 11a5 5 0 0 1 7-7 M6 16l7-7',hospital:'M4 21V5h16v16 M9 9h6 M12 6v6 M9 21v-5h6v5',vaccines:'m4 20 3-3 M7 14l3 3 9-9-3-3z M14 3l7 7',timeline:'M6 3v18 M3 7h6 M3 16h6 M12 7h8 M12 16h8',results:'M3 20h18 M5 16l5-6 4 3 6-9',search:'M20 11a8 8 0 1 0-5 7l5 3z',growth:'M4 20V4 M4 20h17 M7 16l4-4 4 1 5-8',episodes:'M3 12h5l3-7 4 14 3-7h3',notifications:'M5 17h14l-2-4V8a5 5 0 0 0-10 0v5z M10 21h4',family:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-3a7 7 0 0 1 14 0v3 M17 4a4 4 0 0 1 0 8 M18 15a5 5 0 0 1 4 6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2'};
Object.keys(paths).forEach(k=>ICONS[k]=`<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[k]}"/></svg>`);
const baseReload=reload,baseLayout=layout,baseModal=modalHtml,baseExecute=execute,baseSubmit=submitForm,baseRender=render,baseDocs=docsView,baseMeds=medsView,baseHospital=hospitalView,baseVaccines=vaccinesView;
const baseDateFields=['start_date','end_date','due_date','next_due_date','given_date','record_date','prescription_date','actual_start_date','actual_stop_date','admitted_on','discharged_on','started_on','ended_on'];
const clean=o=>{for(const k of baseDateFields)if(o[k]==='')o[k]=null;for(const k of ['source_document_id','discharge_document_id','admission_id','source_page'])if(k in o)o[k]=o[k]?Number(o[k]):k==='source_page'?1:null;return o;};
const source=(id,page)=>id?`<button class="btn ghost small" data-action="source-page" data-id="${id}" data-page="${page||1}">Source #${id} · page ${page||1}</button>`:'<span class="muted tiny">Source not attached</span>';
const localClock=()=>{const p=S.patients.find(p=>p.id===S.pid);const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:p?.tz||'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());return parts.replace(' ','T');};
async function downloadEndpoint(path,name){const r=await request(path),blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
reload=async function(){await baseReload();if(!S.pid||!S.token)return;const pid=S.pid;const names=['admissions','administrations','growth','episodes','notifications','family','lab-trends'];try{const values=await Promise.all(names.map(n=>request(`/patients/${pid}/${n}`)));if(pid!==S.pid)return;names.forEach((n,i)=>S[n==='lab-trends'?'trends':n]=values[i]);render();}catch(e){fail(e);}};
layout=function(content){let html=baseLayout(content);html=html.replace('<div class="top-actions">',`<div class="top-actions"><select class="select mobile-destination" id="destination" aria-label="Open section">${NAV.map(([k,v])=>`<option value="${k}" ${S.tab===k?'selected':''}>${v}</option>`).join('')}</select><button class="btn ghost small theme-button" data-action="theme" aria-label="Toggle light or dark theme">◐</button>`);return html;};
function ageLabel(dob){const now=(S.today?.date||localClock().slice(0,10)).split('-').map(Number),born=dob.split('-').map(Number);let months=(now[0]-born[0])*12+now[1]-born[1]-(now[2]<born[2]?1:0);return months<24?`${months} months old`:`${Math.floor(months/12)} years, ${months%12} months`;}
todayView=function(){const p=S.patients.find(p=>p.id===S.pid),today=S.today?.date||localClock().slice(0,10);const nextVax=S.vaccines.filter(v=>v.confirmed&&v.due_date&&!v.given_date&&v.due_date>=today).sort((a,b)=>a.due_date.localeCompare(b.due_date))[0];const nextVisit=S.visits.filter(v=>v.confirmed&&v.status==='planned'&&v.planned_at.slice(0,10)>=today).sort((a,b)=>a.planned_at.localeCompare(b.planned_at))[0];const current=S.meds.filter(m=>m.status==='verified'&&(!m.end_date||m.end_date>=today));const pending=S.docs.filter(d=>d.extraction_status!=='reviewed').length+S.meds.filter(m=>m.status==='draft').length+S.vaccines.filter(v=>!v.confirmed).length;return `${header('A LITTLE CARE, EVERY DAY',`${p.name}’s health, all together.`,`${ageLabel(p.dob)} · Born ${fmt(p.dob)} · ${p.tz}${p.relationship&&p.relationship!=='other'?' · '+p.relationship:''}`,`<button class="btn" data-action="upload">＋ Upload a report</button>`)}<div class="hero"><div><span class="eyebrow">YOUR FAMILY HEALTH JOURNAL</span><h1>More clarity.<br>${['infant','toddler','child'].includes(p.age_group)?'More room for childhood.':'More room for living.'}</h1><p>Every report, appointment and ${['infant','toddler','child'].includes(p.age_group)?'little milestone':'daily detail'}, kept together for the people who care for ${esc(p.name)}.</p><div class="pillrow"><button class="btn hero-button" data-action="scan-card">Scan vaccination card</button><button class="btn hero-button" data-tab="timeline">Explore the timeline →</button></div></div><div class="hero-art" aria-hidden="true"><div class="orbit o1"></div><div class="orbit o2"></div><span>♡</span><i>✦</i></div></div><div class="cards"><div class="card statcard"><div><span class="eyebrow">TODAY’S CARE</span><div class="stat">${S.today?.reminders?.length||0}</div><span class="muted">Confirmed reminders</span></div>${ICONS.today}</div><div class="card statcard"><div><span class="eyebrow">PRESCRIBED COURSES</span><div class="stat">${current.length}</div><span class="muted">Actual doses recorded separately</span></div>${ICONS.medicines}</div><div class="card statcard"><div><span class="eyebrow">NEEDS YOUR REVIEW</span><div class="stat">${pending}</div><button class="btn ghost small" data-tab="documents">Review records →</button></div>${ICONS.documents}</div></div><div class="columns"><div class="stack"><div class="card"><div class="sectionhead"><h2>Today’s care schedule</h2><span class="muted tiny">${fmt(today)}</span></div>${S.today?.reminders?.length?S.today.reminders.map(reminderRow).join(''):empty('A clear day. No confirmed care reminders are scheduled.')}</div><div class="card"><div class="sectionhead"><h2>Recent reports</h2><button class="btn ghost small" data-tab="documents">View all →</button></div>${S.docs.slice(0,4).map(d=>`<div class="entry"><span class="roundicon">${ICONS.documents}</span><div class="entrybody"><b>${esc(d.title)}</b><div class="desc">${fmt(d.record_date)} · ${esc(d.category)}</div></div><button class="btn alt small" data-action="review" data-id="${d.id}">${d.extraction_status==='reviewed'?'View':'Review'}</button></div>`).join('')||empty('Your original reports will live here. Start by uploading a document.')}</div><div class="card"><h2>Current prescribed courses</h2>${current.map(m=>`<div class="entry"><div class="entrybody"><b>${esc(m.name)}</b><div class="desc">${fmt(m.start_date)} — ${fmt(m.end_date)} · ${m.reported_given_count} recorded administrations</div></div><button class="btn ghost small" data-action="med-detail" data-id="${m.id}">Details →</button></div>`).join('')||empty('No verified current courses.')}</div></div><div class="stack"><div class="card appointment-card"><span class="eyebrow">NEXT VACCINATION</span><h2>${nextVax?esc(nextVax.name):'No confirmed appointment'}</h2><p class="muted">${nextVax?fmt(nextVax.due_date):'Your vaccination card’s verified dates appear here.'}</p><button class="btn alt" data-tab="vaccines">Open vaccination chart →</button></div><div class="card"><span class="eyebrow">NEXT HOSPITAL VISIT</span><h2>${nextVisit?esc(nextVisit.facility):'Nothing scheduled'}</h2><p class="muted">${nextVisit?dtfmt(nextVisit.planned_at):'Add the appointment confirmed by your hospital.'}</p><button class="btn ghost" data-tab="hospital">Hospital care →</button></div><div class="card"><h2>A question about the past?</h2><p class="muted">Find when a medicine was prescribed or compare earlier reports, with links to the evidence.</p><button class="btn alt" data-tab="search">Ask HealthBook AI →</button></div></div></div>`;};
docsView=function(){return `<div class="dropzone" id="dropzone" tabindex="0" role="button" data-action="upload" aria-label="Upload medical documents">${ICONS.documents}<b>Drop medical reports here</b><span>PDF, JPEG, PNG or HEIC · multiple files welcome · 12 MB per file</span><div class="pillrow"><button class="btn alt small" data-action="scan-prescription">Scan prescription</button><button class="btn alt small" data-action="scan-card">Scan vaccination card</button></div></div>`+baseDocs();};
medsView=function(){return baseMeds()+`<div class="card section-gap"><h2>Course details & administration history</h2><div class="course-grid">${S.meds.map(m=>`<button class="course-card" data-action="med-detail" data-id="${m.id}"><span class="eyebrow">COURSE #${m.id}</span><b>${esc(m.name)}</b><span>${fmt(m.start_date)} → ${fmt(m.end_date)}</span><span>${m.reported_given_count||0} given events · ${esc(m.status)}</span></button>`).join('')}</div></div>`;};
hospitalView=function(){return `${header('CONTINUITY OF CARE','Admissions & treatment visits','Appointments and actual administrations have separate records.',`<button class="btn alt" data-action="new-admission">Add admission</button><button class="btn alt" data-action="visit-series">Schedule a course of visits</button>`)}<div class="course-grid">${S.admissions.map(a=>`<div class="card"><span class="eyebrow">ADMISSION #${a.id}</span><h2>${esc(a.facility)}</h2><p>${fmt(a.admitted_on)} — ${fmt(a.discharged_on)}</p><p class="muted">${esc(a.doctor)} · ${esc(a.diagnosis||'Diagnosis not documented')}</p><p>${esc(a.treatment_plan)}</p>${source(a.source_document_id,a.source_page)}</div>`).join('')}</div>${baseHospital()}<div class="card section-gap"><h2>Record what actually happened</h2>${S.visits.map(v=>`<div class="entry"><div class="entrybody"><b>${esc(v.facility)}</b><div class="desc">${dtfmt(v.planned_at)} · ${esc(v.status)}</div></div><button class="btn alt small" data-action="reschedule" data-id="${v.id}">Reschedule</button><button class="btn alt small" data-action="new-administration" data-id="${v.id}">Record treatment</button></div>`).join('')||empty('Create a visit before attaching an administration record.')}<h3 class="section-gap">Confirmed from administration records</h3>${S.administrations.map(a=>`<div class="entry"><div class="entrybody"><b>${esc(a.medication)}</b><div class="desc">${dtfmt(a.occurred_at)} · Recorded dose ${esc(a.recorded_dose||'unknown')} · ${esc(a.recorded_route)}</div></div>${source(a.source_document_id,a.source_page)}</div>`).join('')||empty('No actual hospital administrations recorded.')}</div>`;};
vaccinesView=function(){const today=S.today?.date||localClock().slice(0,10);return `${baseVaccines()}<div class="pillrow section-gap"><button class="btn" data-action="scan-card">Scan vaccination card</button><button class="btn alt" data-action="vax-export">Download vaccination chart</button><button class="btn alt" data-action="iap-reference">IAP / private schedule reference</button></div><div class="card section-gap"><h2>Vaccination journey</h2>${S.vaccines.map(v=>`<div class="entry">${wordDate(v.given_date||v.due_date||'')}<div class="entrybody"><b>${esc(v.name)} ${esc(v.dose_label)}</b><div class="desc">${v.confirmed&&v.given_date?'Verified administration':!v.confirmed?'Uncertain record — verification needed':v.due_date<today?'Overdue confirmed appointment — pediatrician review':'Confirmed appointment'} · ${esc(v.schedule)} · Clinic ${esc(v.facility||'not recorded')}</div><div class="desc">Reminders: ${esc(v.reminder_days)} days before the confirmed date</div>${source(v.source_document_id,v.source_page)}</div></div>`).join('')||empty('Scan a card to start your vaccination history.')}</div>`;};
function lineChart(points,label){const ps=points.filter(p=>p.value!==null&&Number.isFinite(Number(p.value)));if(!ps.length)return empty('No verified numeric measurements to plot.');const values=ps.map(p=>Number(p.value)),lo=Math.min(...values),hi=Math.max(...values),span=hi-lo||1;const coords=ps.map((p,i)=>[30+(i*520/Math.max(ps.length-1,1)),155-(Number(p.value)-lo)*115]);return `<svg class="trend-chart" viewBox="0 0 590 200" role="img" aria-label="${esc(label)}"><path d="M30 25v135h530" fill="none" stroke="var(--line)"/><polyline points="${coords.map(p=>p.join(',')).join(' ')}" fill="none" stroke="var(--brand)" stroke-width="2.5"/>${ps.map((p,i)=>`<g tabindex="0"><circle cx="${coords[i][0]}" cy="${coords[i][1]}" r="5" fill="var(--brand)"/><title>${esc(p.date)}: ${esc(p.value)} ${esc(label)}</title><text x="${coords[i][0]}" y="${coords[i][1]-12}" text-anchor="middle" fill="var(--ink)" font-size="11">${esc(p.value)}</text></g>`).join('')}<text x="30" y="185" fill="var(--muted)" font-size="11">${esc(ps[0].date)}</text><text x="550" y="185" text-anchor="end" fill="var(--muted)" font-size="11">${esc(ps.at(-1).date)}</text></svg>`;}
resultsView=function(){return `${header('EVERY RESULT IN CONTEXT','Laboratory analysis','Original units, specimen types and laboratory reference intervals are preserved.',`<button class="btn alt" data-action="labs-export">Export table</button><button class="btn" data-action="new-lab">Add result</button>`)}<div class="note">Only verified numeric results with matching units and specimen types are plotted together. Printed ranges may not be suitable for this profile’s age.</div><div class="stack section-gap">${S.trends.groups.map(g=>`<div class="card"><div class="sectionhead"><h2>${esc(g.test_name)}</h2><span class="muted">${esc(g.unit||'Unit missing')} · ${esc(g.specimen||'Specimen missing')}</span></div>${lineChart(g.points.filter(p=>p.plot_eligible).map(p=>({date:p.record_date,value:p.numeric_value})),g.unit)}${g.points.map(p=>`<div class="entry"><div class="entrybody"><b>${fmt(p.record_date)} · ${esc(p.value)} ${esc(p.unit)}</b><div class="desc">Reference interval: ${esc(p.reference_range||'Not printed / unknown')} · ${p.verified?'Caregiver verified':'Unverified'}${p.organism?' · '+esc(p.organism):''}</div></div>${source(p.source_document_id,p.source_page)}</div>`).join('')}</div>`).join('')||empty('Add laboratory measurements from your original reports.')}</div>`;};
function growthView(){return `${header('THE LITTLE MILESTONES','Growth & development','Your own recorded measurements over time. No adult ranges or inferred percentiles.',`<button class="btn" data-action="new-growth">Add measurement</button>`)}<div class="columns"><div class="card"><h2>Weight · kg</h2>${lineChart(S.growth.filter(g=>g.weight_kg).map(g=>({date:g.record_date,value:Number(g.weight_kg)})),'kg')}</div><div class="card"><h2>Length · cm</h2>${lineChart(S.growth.filter(g=>g.length_cm).map(g=>({date:g.record_date,value:Number(g.length_cm)})),'cm')}</div></div><div class="card section-gap"><h2>Measurements & moments</h2>${S.growth.map(g=>`<div class="entry">${wordDate(g.record_date)}<div class="entrybody"><b>${esc(g.milestone||'Growth measurement')}</b><div class="desc">Weight ${esc(g.weight_kg||'unknown')} kg · Length ${esc(g.length_cm||'unknown')} cm · Head ${esc(g.head_cm||'unknown')} cm</div><p>${esc(g.note)}</p></div>${source(g.source_document_id,g.source_page)}</div>`).join('')||empty('Record the measurements and milestones you want to remember.')}</div>`;}
function episodesView(){return `${header('A CONNECTED HISTORY','Illness episodes','Link the evidence from each illness without assuming infections are the same.',`<button class="btn alt" data-action="compare-ecoli">Compare E. coli records</button><button class="btn" data-action="new-episode">Add illness episode</button>`)}<div class="stack">${S.episodes.map(e=>`<div class="card"><span class="eyebrow">${fmt(e.started_on)} — ${fmt(e.ended_on)}</span><h2>${esc(e.title)}</h2><p>Symptoms: ${esc(e.symptoms||'Not documented')}</p><p>Documented diagnosis: ${esc(e.documented_diagnosis||'Not documented')}</p><p class="muted">${esc(e.notes)}</p>${source(e.source_document_id,e.source_page)}<div class="muted tiny">${e.links.map(l=>`${esc(l.kind)} #${l.id}`).join(' · ')}</div></div>`).join('')||empty('Each episode can link to its own reports, consultations and treatments.')}</div>`;}
function notificationsView(){return `${header('GENTLE NUDGES','Notification center','Acknowledging a notification does not record a treatment or vaccination.')}<div class="headnote">Background worker: <b>${S.notifications.worker_running?'running':'not detected'}</b> · Remote push: <b>${S.notifications.push_configured?'configured':'not configured'}</b>. Register a physical phone in the mobile app for alerts when the website is closed.</div><div class="card">${S.notifications.items.map(n=>`<div class="entry"><div class="entrybody"><b>${esc(n.title)}</b><div class="desc">${dtfmt(n.due_at)} · ${esc(n.channel)} · ${esc(n.status)}${n.error_code?' · '+esc(n.error_code):''}</div></div>${n.acknowledged_at?'Acknowledged':`<button class="btn alt small" data-action="ack" data-id="${n.id}">Acknowledge</button><button class="btn ghost small" data-action="snooze" data-id="${n.id}">Snooze 15 min</button>`}</div>`).join('')||empty('The background worker will place due care reminders here.')}</div>`;}
function familyView(){return `${header('YOUR TRUSTED CIRCLE','Family access','Only your primary guardian can invite or remove caregivers.')}<div class="columns"><div class="card"><h2>People with access</h2>${S.family.members.map(m=>`<div class="entry"><div class="entrybody"><b>${esc(m.email)}</b><div class="desc">${esc(m.role)}</div></div>${S.family.owner?`<button class="btn ghost small" data-action="revoke" data-id="${m.id}">Remove access</button>`:''}</div>`).join('')||empty('No additional caregivers have access.')}${S.family.owner?`<form id="invite-form" class="section-gap">${field('Caregiver’s registered email','email','email','',true)}<label class="field">Permission<select name="role"><option value="viewer">View records only</option><option value="editor">View and edit care records</option></select></label><label class="check"><input type="checkbox" name="guardian_permission" required/> I authorize this person to access this profile’s medical records.</label><button class="btn">Create invitation code</button></form><div id="invitation-result"></div>`:''}</div><div class="card"><h2>Accept an invitation</h2><p class="muted">Sign in with the email the guardian invited, then paste the code they shared with you.</p><form id="accept-form">${field('Invitation code','invitation_code','text','',true)}<button class="btn alt">Accept invitation</button></form></div></div>`;}
function settingsView(){const p=S.patients.find(p=>p.id===S.pid);return `${header('YOUR FAMILY WORKSPACE','Profile & settings','Manage privacy, preferences and copies of your records.')}<div class="columns"><div class="card"><h2>Health profile</h2><form id="profile-form">${field('Full name','name','text',p.name,true)}${field('Date of birth','dob','date',p.dob,true)}${profileMetaFields(p.relationship||'',p.sex||'')}${field('Timezone','tz','text',p.tz,true)}<p class="muted tiny">Changing timezone resets schedule confirmations, so existing clock times can be checked again.</p><button class="btn">Save profile</button></form></div><div class="stack"><div class="card"><h2>Your records, in your hands</h2><p class="muted">Exports contain private health information. Store and share them carefully.</p><div class="pillrow"><button class="btn alt" data-action="summary">Doctor summary</button><button class="btn alt" data-action="full-export">Complete data & originals</button><button class="btn alt" data-action="audit">View audit trail</button></div></div><div class="card"><h2>Appearance</h2><button class="btn alt" data-action="theme">Toggle light / dark</button></div><div class="card"><h2>Account deletion</h2><p class="muted">Permanently removes this account and every profile it owns. Download an export first if you want a copy.</p><button class="btn danger" data-action="delete-account">Delete my account…</button></div></div></div>`;}
render=function(){if(!S.token||!S.patients.length){baseRender();return;}const extra={growth:growthView,episodes:episodesView,notifications:notificationsView,family:familyView,settings:settingsView};if(extra[S.tab])el('#app').innerHTML=layout(extra[S.tab]());else baseRender();if(S.modal==='review')loadReviewPage();};
const reviewFields={vaccine:[['name','Vaccine / combination'],['dose_label','Dose number / booster'],['given_date','Actual date given','date'],['due_date','Appointment date for this dose, if recorded','date'],['next_due_date','Next dose appointment on card','date'],['next_dose_label','Next dose label, only if recorded'],['batch_number','Batch number'],['facility','Clinic / hospital'],['doctor','Doctor'],['reminder_days','Reminder days before appointment'],['note','Remarks']],medicine:[['name','Medication name'],['instructions','Exact prescribed directions'],['generic_name','Generic name, if established'],['brand_name','Brand'],['dosage','Written dose'],['dose_unit','Dose unit'],['route','Written route'],['frequency','Written frequency'],['prescription_date','Prescription date','date'],['start_date','Planned start','date'],['end_date','Planned end, if documented','date'],['prescribing_doctor','Prescriber'],['indication','Documented indication']],observation:[['test_name','Test'],['value','Printed result'],['unit','Original unit'],['specimen','Specimen'],['record_date','Sample / result date','date'],['reference_range','Printed reference interval'],['organism','Reported organism'],['culture_findings','Culture findings'],['susceptibility','Susceptibility from report']],episode:[['title','Episode'],['started_on','Start','date'],['symptoms','Symptoms'],['documented_diagnosis','Documented diagnosis'],['notes','Notes']]};
const RV_KIND={medicine:'Medicine',vaccine:'Vaccine',observation:'Observation',episode:'Episode'};
function rvNormalize(r){(r.items||[]).forEach(it=>{if(it.included===undefined)it.included=!!it.verified;if(!it.fields)it.fields={};});return r;}
function rvNumbers(items){const seen={};return items.map(it=>seen[it.kind]=(seen[it.kind]||0)+1);}
function rvErrMap(){const m={};for(const e of (S.reviewErrors||[])){if(e.index==null)continue;(m[e.index]=m[e.index]||{})[e.field||'_row']=(m[e.index][e.field||'_row']||[]).concat(e.message.replace(/^Page \d+ · [A-Za-z]+ row \d+: /,''));}return m;}
function rvSummary(){const errs=S.reviewErrors||[];if(!errs.length)return '';return `<div class="rv-summary" id="review-errors" role="alert"><b>${esc(S.reviewErrorTitle||`${errs.length} item${errs.length===1?'':'s'} need review before this document can be confirmed.`)}</b><ul>${errs.map(e=>`<li><button type="button" class="rv-link" data-action="review-goto" data-index="${e.index??''}" data-field="${esc(e.field||'')}" data-page="${e.page??''}">${esc(e.message)}</button></li>`).join('')}</ul></div>`;}
function rvIncludedCount(){return (S.review.items||[]).filter(it=>it.included).length;}
function reviewHtml(){const r=rvNormalize(S.review);const nums=rvNumbers(r.items);const em=rvErrMap();const inc=rvIncludedCount();
 const fieldBox=(i,k,label,type,value)=>{const msgs=(em[i]||{})[k]||[];return `<div class="rv-f ${msgs.length?'rv-bad':''}" data-rvfield="r${i}_${k}">${field(label,`r${i}_${k}`,type||'text',value)}${msgs.map(m=>`<div class="rv-msg">${esc(m)}</div>`).join('')}</div>`;};
 const row=(item,i)=>{const msgs=em[i]||{};const bad=Object.keys(msgs).length>0;const suggested=!!item.raw_line;return `<fieldset class="review-item ${item.included?'rv-in':'rv-out'} ${bad?'rv-bad':''}" data-rvrow="${i}" data-page="${item.page}"><legend>${esc(RV_KIND[item.kind]||item.kind)} row ${nums[i]} · source page ${item.page}</legend><div class="rv-head"><label class="check rv-include"><input type="checkbox" name="r${i}_included" data-action="review-include" data-index="${i}" ${item.included?'checked':''}/> <span><b>Include in history</b> — I checked this row against the original</span></label><button class="btn ghost small" type="button" data-action="remove-review" data-index="${i}">Remove row</button></div>${suggested?`<p class="muted tiny">${item.included?'':'Suggested from the text recognition; not part of the history unless you include it. '}Recognised text: ${esc(item.raw_line)}</p>`:''}${item.date_candidates?.length?`<p class="note">Dates seen: ${item.date_candidates.map(esc).join(', ')}. Numeric dates may be ambiguous; enter the date only when you are sure.</p>`:''}${(msgs._row||[]).map(m=>`<div class="rv-msg">${esc(m)}</div>`).join('')}<div class="rv-fields ${item.included?'':'rv-collapsed'}"><div class="formgrid">${reviewFields[item.kind].map(([k,label,type])=>fieldBox(i,k,label,type,item.fields[k])).join('')}</div>${fieldBox(i,'page','Source page','number',item.page).replace('type="number"',`type="number" min="1" max="${r.document.page_count}"`)}${item.kind==='vaccine'?`<label class="check"><input type="checkbox" name="r${i}_activate" ${item.activate_reminders?'checked':''}/> This next appointment is confirmed; activate reminders for it.</label><label class="check"><input type="checkbox" name="r${i}_duplicate" ${item.duplicate_confirmed?'checked':''}/> If a matching dose already exists, I verified this is a separate record.</label>`:''}</div></fieldset>`;};
 const ackBad=(S.reviewErrors||[]).some(e=>e.field==='checked_against_original');
 return `<div class="review-grid"><section class="original-pane"><div class="sectionhead"><h3>Original document</h3><select id="review-page" class="select" aria-label="Original page">${Array.from({length:r.document.page_count},(_,i)=>`<option value="${i+1}">Page ${i+1}</option>`).join('')}</select></div><img id="original-page" alt="Original medical document page"/><button class="btn ghost" data-action="download" data-id="${r.document.id}">Download original</button></section><section><p class="note">Read the original beside each row. Only rows you <b>include</b> become medical history; everything else stays as the document’s transcription. Leave unreadable information blank and never guess a dose or a date.</p>${r.status==='confirmed'?'<div class="headnote">This review has been saved. Prescription reminders still require separate confirmation.</div>':`<form id="review-form" novalidate>${rvSummary()}<div class="rv-counts muted tiny">${r.items.length} row${r.items.length===1?'':'s'} · <b id="rv-included-count">${inc}</b> included in history</div>${r.items.map(row).join('')}<div class="pillrow">${['vaccine','medicine','observation'].map(k=>`<button type="button" class="btn alt small" data-action="add-review" data-kind="${k}">Add ${k} row</button>`).join('')}</div><details class="section-gap"><summary>Correct transcription text</summary><p class="muted tiny">The raw transcription is saved with the document. It is not checked line by line and never becomes history by itself.</p><textarea class="review-text" name="text">${esc(r.text)}</textarea></details><label class="check ${ackBad?'rv-bad':''}" id="rv-ack"><input name="checked_against_original" type="checkbox" ${r.checked_against_original?'checked':''}/> I verified all included entries. No unreadable field has been guessed.</label><div class="formfoot"><button type="button" class="btn alt" data-action="save-review">Save review draft</button><button class="btn" type="submit" id="rv-submit">${inc?'Confirm and save to history':'Save reviewed document'}</button></div></form>`}<div class="section-gap"><button class="btn ghost small" data-action="vision-consent" data-id="${r.document.id}">Use configured AI vision for difficult text…</button></div></section></div>`;}
let previewUrl;
function rvGoto(index,fieldName,page){const sel=el('#review-page');if(page&&sel&&String(sel.value)!==String(page)){sel.value=String(page);loadReviewPage();}
 let target=null;if(index!=null){const fs=document.querySelector(`[data-rvrow="${index}"]`);if(fs){fs.querySelector('.rv-fields')?.classList.remove('rv-collapsed');target=(fieldName&&fs.querySelector(`[name="r${index}_${fieldName}"]`))||fs.querySelector('[name$="_included"]');(fs).scrollIntoView({block:'center',behavior:'smooth'});}}
 else if(fieldName==='checked_against_original'){target=el('#rv-ack input');el('#rv-ack')?.scrollIntoView({block:'center',behavior:'smooth'});}
 if(target)setTimeout(()=>target.focus({preventScroll:true}),250);}
let reviewPageSeq=0;
async function loadReviewPage(){if(!S.review||!el('#original-page'))return;const id=S.review.document.id,page=el('#review-page')?.value||1;const seq=++reviewPageSeq;try{const r=await request(`/documents/${id}/pages/${page}`),blob=await r.blob();if(seq!==reviewPageSeq)return;/* a newer page was requested meanwhile */const url=URL.createObjectURL(blob);if(el('#original-page'))el('#original-page').dataset.page=String(page);if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=url;if(el('#original-page'))el('#original-page').src=url;}catch(e){fail(e);}}
function collectReview(){const f=el('#review-form'),r=S.review;const items=r.items.map((it,i)=>{const fields={...it.fields};for(const [k] of reviewFields[it.kind])fields[k]=val(f,`r${i}_${k}`);clean(fields);if(it.kind==='vaccine')fields.reminder_days=fields.reminder_days||'7,1,0';const included=!!f.elements[`r${i}_included`]?.checked;return {...it,fields,page:Number(val(f,`r${i}_page`))||it.page||1,included,verified:included,activate_reminders:!!f.elements[`r${i}_activate`]?.checked,duplicate_confirmed:!!f.elements[`r${i}_duplicate`]?.checked};});return {items,text:val(f,'text'),version:r.version,checked_against_original:!!f.elements.checked_against_original?.checked};}
function dialog(title,body,wide=false){return `<div class="modalbg"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalheader"><h2>${esc(title)}</h2><button class="close" data-action="close" aria-label="Close">×</button></div>${body}</div></div>`;}
const textArea=(label,name,value='')=>`<label class="field">${esc(label)}<textarea name="${name}">${esc(value)}</textarea></label>`;
const saveButton='<div class="formfoot"><button class="btn" type="submit">Save record</button></div>';
modalHtml=function(){const x=S.prefill||{};
 if(S.modal==='review')return dialog('Document extraction review',reviewHtml(),true);
 if(S.modal==='source')return dialog('Original source',`<img class="source-image" src="${esc(S.sourceURL)}" alt="Original document page"/>`,true);
 if(S.modal==='read-only')return dialog(x.title,`<div class="pre">${esc(x.text)}</div>`);
 if(S.modal==='med-detail'){const m=S.detail;return dialog(m.name,`<p>${esc(m.instructions)}</p><div class="pillrow">${status(m.status)}${source(m.source_document_id,m.source_page)}</div><p class="muted">Prescribed ${fmt(m.prescription_date)} · Planned ${fmt(m.start_date)} to ${fmt(m.end_date)}<br>Actual start ${fmt(m.actual_start_date)} · Actual stop ${fmt(m.actual_stop_date)}</p><h3>Actual administration history</h3>${m.events.map(e=>`<div class="entry"><div>${esc(e.event_type)} · ${dtfmt(e.occurred_at)}<div class="desc">${esc(e.source)} · Prescription version ${e.medicine_version} · ${esc(e.note)}</div></div></div>`).join('')||empty('No actual doses recorded.')}<h3 class="section-gap">Prescription revisions</h3>${m.revisions.map(r=>`<details><summary>Version ${r.version}</summary><p>${esc(r.snapshot.instructions)}</p></details>`).join('')||'<p class="muted">No revisions.</p>'}<button class="btn alt" data-action="stop-med" data-id="${m.id}">Record course stopped</button>`);}
 if(S.modal==='stop-med')return dialog('Record an actual course stop',`<form id="stop-form"><input type="hidden" name="id" value="${x.id}"/>${field('Actual start, if known','actual_start_date','date')}${field('Actual stop date','actual_stop_date','date','',true)}${textArea('Reason / clinician instruction','reason')}${saveButton}</form>`);
 if(S.modal==='new-growth')return dialog('Growth & development',`<form id="growth-form">${field('Measurement date','record_date','date',localClock().slice(0,10),true)}<div class="formgrid">${field('Weight · kg','weight_kg','number','',false,'step="0.001" min="0.001"')}${field('Length · cm','length_cm','number','',false,'step="0.1" min="0.1"')}${field('Head circumference · cm','head_cm','number','',false,'step="0.1" min="0.1"')}</div>${field('Development milestone','milestone')}${textArea('Notes','note')}${docSelect()}${saveButton}</form>`);
 if(S.modal==='new-admission')return dialog('Hospital admission',`<form id="admission-form">${field('Hospital','facility','text','',true)}${field('Treating doctor','doctor')}<div class="formgrid">${field('Admission date','admitted_on','date','',true)}${field('Discharge date','discharged_on','date')}</div>${textArea('Diagnosis exactly as documented','diagnosis')}${textArea('Prescribed treatment plan','treatment_plan')}${docSelect()}<label class="field">Discharge summary<select name="discharge_document_id">${optdocs()}</select></label>${saveButton}</form>`);
 if(S.modal==='new-episode')return dialog('Illness episode',`<form id="episode-form">${field('Episode title','title','text','',true)}<div class="formgrid">${field('First symptoms / start','started_on','date','',true)}${field('End, if known','ended_on','date')}</div>${textArea('Symptoms','symptoms')}${textArea('Diagnosis as documented','documented_diagnosis')}${textArea('Notes / follow-up','notes')}${docSelect()}<label class="field">Linked medication course<select name="medicine_link"><option value="">None</option>${S.meds.map(m=>`<option value="${m.id}">${esc(m.name)} · course #${m.id}</option>`).join('')}</select></label><label class="field">Linked laboratory result<select name="observation_link"><option value="">None</option>${S.observations.map(o=>`<option value="${o.id}">${esc(o.test_name)} · ${fmt(o.record_date)}</option>`).join('')}</select></label>${saveButton}</form>`);
 if(S.modal==='new-administration')return dialog('Actual hospital administration',`<form id="administration-form"><input type="hidden" name="visit_id" value="${x.id}"/>${field('Medication written in hospital administration record','medication','text','',true)}${field('Actual local date and time','occurred_at','datetime-local',localClock(),true)}${field('Dose as recorded','recorded_dose')}${field('Route as recorded','recorded_route')}${docSelect()}${field('Source page','source_page','number',1,true,'min="1" max="35"')}${textArea('Notes','note')}<label class="check"><input type="checkbox" name="checked_administration_record" required/> I checked the actual hospital administration record.</label>${saveButton}</form>`);
 if(S.modal==='reschedule')return dialog('Confirmed revised appointment',`<form id="reschedule-form"><input type="hidden" name="id" value="${x.id}"/>${field('New confirmed appointment','planned_at','datetime-local','',true)}${docSelect()}<label class="check"><input type="checkbox" name="checked_against_source" required/> I checked the revised date against the hospital source.</label>${saveButton}</form>`);
 if(S.modal==='visit-series')return dialog('Day-by-day hospital appointments',`<form id="series-form">${field('Hospital','facility','text','',true)}${field('Purpose from hospital plan','purpose','text','',true)}${field('First appointment','planned_at','datetime-local','',true)}${field('Number of daily visits explicitly prescribed','count','number',5,true,'min="1" max="30"')}${docSelect()}<label class="field">Admission<select name="admission_id"><option value="">Not linked</option>${S.admissions.map(a=>`<option value="${a.id}">${esc(a.facility)} · ${fmt(a.admitted_on)}</option>`).join('')}</select></label><p class="note">Use only for a hospital-confirmed daily appointment series. No medication, dose or infusion rate is generated.</p><label class="check"><input type="checkbox" name="checked" required/> I checked the daily dates and time against the hospital plan.</label>${saveButton}</form>`);
 if(S.modal==='delete-account')return dialog('Permanently delete your account',`<form id="delete-form">${field('Current password','password','password','',true)}${field('Type DELETE MY ACCOUNT AND OWNED CHILD RECORDS','confirmation','text','',true)}<button class="btn danger">Permanently delete</button></form>`);
 let html=baseModal();
 if(S.modal==='upload')html=html.replace('name="file" accept=', 'name="file" multiple accept=').replace('.pdf,.jpg,.jpeg,.png,','.pdf,.jpg,.jpeg,.png,.heic,').replace('<option value="vaccination_card">',`<option value="vaccination_card" ${S.uploadCategory==='vaccination_card'?'selected':''}>`).replace('<option value="prescription">',`<option value="prescription" ${S.uploadCategory==='prescription'?'selected':''}>`);
 if(['new-med','edit-med'].includes(S.modal)){const m=S.meds.find(m=>m.id===x.id)||x;html=html.replace('<div class="formfoot">',`<details><summary>Medication details & source page</summary><div class="formgrid">${reviewFields.medicine.filter(([k])=>!['name','instructions','start_date','end_date'].includes(k)).map(([k,label,type])=>field(label,k,type||'text',m[k])).join('')}${field('Source page','source_page','number',m.source_page||1)}</div></details><div class="formfoot">`);}
 if(['new-vaccine','edit-vaccine'].includes(S.modal)){const v=S.vaccines.find(v=>v.id===x.id)||x;html=html.replace('<div class="formfoot">',`<div class="formgrid">${field('Batch number','batch_number','text',v.batch_number)}${field('Clinic / hospital','facility','text',v.facility)}${field('Doctor','doctor','text',v.doctor)}${field('Source page','source_page','number',v.source_page||1)}${field('Reminder days before date (comma separated)','reminder_days','text',v.reminder_days||'7,1,0')}</div><label class="field">Schedule label<select name="schedule"><option value="card">As recorded on card</option><option value="India_UIP" ${v.schedule==='India_UIP'?'selected':''}>Government UIP</option><option value="IAP_private" ${v.schedule==='IAP_private'?'selected':''}>IAP / private clinic</option></select></label>${!v.id?'<label class="check"><input type="checkbox" name="duplicate_confirmed"/> I reviewed a possible matching dose and confirm this is a separate entry.</label>':''}<div class="formfoot">`);}
 if(S.modal==='new-lab')html=html.replace('<div class="formfoot">',`${field('Source page','source_page','number',1)}${field('Reported organism','organism')}${textArea('Culture findings','culture_findings')}${textArea('Antibiotic susceptibility as printed','susceptibility')}<label class="check"><input type="checkbox" name="verified"/> I checked this result against the report.</label><div class="formfoot">`);
 if(S.modal==='med-event')html=html.replace('<div class="formfoot">',`${docSelect()}${field('Source page','source_page','number',1)}<div class="formfoot">`);
 return html;
};
async function openReview(id){let d=await request(`/documents/${id}/extraction`);if(!d.text){try{await request(`/documents/${id}/extract`,{method:'POST'});}catch(e){toast(e.message+' You can still transcribe manually.');}}S.review=await request(`/documents/${id}/review`);S.reviewErrors=null;S.modal='review';render();}
execute=async function(action,id,b){switch(action){
 case'theme':{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('babycare_theme',next);return;}
 case'scan-card':S.uploadCategory='vaccination_card';return openModal('upload');case'scan-prescription':S.uploadCategory='prescription';return openModal('upload');
 case'extract':case'review':return openReview(id);
 case'source-page':{const r=await request(`/documents/${id}/pages/${b.dataset.page||1}`);if(S.sourceURL)URL.revokeObjectURL(S.sourceURL);S.sourceURL=URL.createObjectURL(await r.blob());return openModal('source');}
 case'add-review':{Object.assign(S.review,collectReview());S.review.items.push({kind:b.dataset.kind,included:true,page:Number(el('#review-page').value),fields:{},verified:false});render();return;}
 case'remove-review':Object.assign(S.review,collectReview());S.review.items.splice(Number(b.dataset.index),1);render();return;
 case'review-include':{const it=S.review.items[Number(b.dataset.index)];if(it){it.included=b.checked;const fs=b.closest('fieldset');fs.classList.toggle('rv-in',b.checked);fs.classList.toggle('rv-out',!b.checked);fs.querySelector('.rv-fields')?.classList.toggle('rv-collapsed',!b.checked);}const n=rvIncludedCount();if(el('#rv-included-count'))el('#rv-included-count').textContent=n;if(el('#rv-submit'))el('#rv-submit').textContent=n?'Confirm and save to history':'Save reviewed document';return;}
 case'review-goto':return rvGoto(b.dataset.index===''?null:Number(b.dataset.index),b.dataset.field,b.dataset.page?Number(b.dataset.page):null);
 case'save-review':{const body=collectReview();const r=await request(`/documents/${S.review.document.id}/review`,{method:'PUT',json:body});Object.assign(S.review,body,r);toast('Review draft saved. No reminders activated.');render();return;}
 case'vision-consent':{const p=await request('/ai/provider');if(!p.configured)throw Error('No AI vision provider is configured. Local OCR and manual review remain available.');if(!confirm(`${p.transmitted}\n\nProvider: ${p.provider}\nModel: ${p.model}\n\nSend this document now?`))return;await request(`/documents/${id}/vision-extract`,{method:'POST',json:{share_document_with_provider:true,provider_host:p.provider}});S.review=await request(`/documents/${id}/review`);render();return;}
 case'med-detail':S.detail=await request(`/medicines/${id}`);return openModal('med-detail');
 case'new-growth':case'new-admission':case'new-episode':case'visit-series':case'delete-account':return openModal(action);
 case'new-administration':case'reschedule':case'stop-med':return openModal(action,{id});
 case'ack':case'snooze':await request(`/notifications/${id}/action`,{method:'POST',json:{action:action==='ack'?'acknowledge':'snooze',minutes:15}});return reload();
 case'revoke':if(confirm('Remove this caregiver’s access to this profile’s records?')){await request(`/patients/${S.pid}/family/${id}`,{method:'DELETE'});await reload();}return;
 case'vax-export':return downloadEndpoint(`/patients/${S.pid}/vaccination-chart.csv`,'vaccination-chart.csv');case'labs-export':return downloadEndpoint(`/patients/${S.pid}/labs.csv`,'laboratory-history.csv');case'full-export':return downloadEndpoint(`/patients/${S.pid}/export`,'healthbook-private-export.zip');
 case'audit':{const rows=await request(`/patients/${S.pid}/audit`);return openModal('read-only',{title:'Medical record audit trail',text:rows.map(r=>`${r.at} · user #${r.user_id} · ${r.action} · ${r.entity} #${r.entity_id}`).join('\n')||'No entries.'});}
 case'compare-ecoli':S.tab='search';render();el('#search-form [name=q]').value='Compare all E. coli-related reports and episodes';el('#search-form').requestSubmit();return;
 case'iap-reference':{await openModal('reference');const r=await request(`/patients/${S.pid}/vaccine-reference?schedule=IAP_private`);el('#reference-list').innerHTML=`<h3>IAP ACVIP 2025 · published April 2026</h3><p class="muted">Separate private-practice reference. Product details and individual timing require pediatrician review.</p>${r.entries.map(e=>`<div class="entry"><div><b>${esc(e.name)}</b><div class="desc">${esc(e.age_window)} · ${fmt(e.reference_date)} · ${esc(e.dose_label)}</div></div></div>`).join('')}<a href="https://www.indianpediatrics.net/may2026/311.pdf" target="_blank" rel="noopener noreferrer">Published reference</a>`;el('[data-action="import-reference"]').remove();return;}
 }return baseExecute(action,id,b);};
submitForm=async function(f){const fd=new FormData(f),o=Object.fromEntries(fd),pid=S.pid;
 if(f.id==='review-form'){const body=collectReview();Object.assign(S.review,body);let res;try{res=await request(`/documents/${S.review.document.id}/review/confirm`,{method:'POST',json:body});}catch(e){if(e.status===422&&e.detail&&Array.isArray(e.detail.errors)){S.reviewErrors=e.detail.errors;S.reviewErrorTitle=e.detail.message;render();const first=e.detail.errors[0];rvGoto(first.index,first.field,first.page);return;}throw e;}
  S.reviewErrors=null;S.modal='';const n=res.created.length;toast(n?`Saved to history: ${n} record${n===1?'':'s'} from this document${res.skipped&&res.skipped.excluded?` · ${res.skipped.excluded} excluded row${res.skipped.excluded===1?'':'s'} left out`:''}. Medication reminders still need prescription confirmation.`:'Reviewed document saved to the Document Library. No history records were created.');return reload();}
 if(f.id==='upload-form'){const files=fd.getAll('file').filter(x=>x.size);if(!files.length)throw Error('Choose at least one document');const failed=[],saved=[];for(const file of files){const form=new FormData();form.append('file',file);form.append('category',fd.get('category'));form.append('title',files.length===1?(fd.get('title')||file.name):file.name);if(fd.get('record_date'))form.append('record_date',fd.get('record_date'));try{saved.push(await request(`/patients/${pid}/documents`,{method:'POST',body:form}));}catch(e){failed.push(file.name+': '+e.message);}}S.modal='';await reload();toast(`${saved.length} original(s) stored.${failed.length?' '+failed.join(' · '):''}`);if(saved.length===1)await openReview(saved[0].id);return;}
 if(f.id==='search-form'){const node=el('#search-results');node.innerHTML='<div class="loading">Finding source records…</div>';try{const r=await request(`/patients/${pid}/ask`,{method:'POST',json:{question:o.q}});node.innerHTML=`<p class="muted tiny">Source-grounded record retrieval · no diagnosis inferred</p>${r.evidence.map(e=>`<div class="answer-evidence"><div class="pillrow">${status(e.verified?'Caregiver verified':'Unverified transcription')}<span class="muted tiny">[${esc(e.citation)}]</span></div><p>${esc(e.statement)}</p>${source(e.source_document_id,e.source_page)}</div>`).join('')||empty(r.answer)}<div class="note">${r.warnings.map(esc).join(' ')}</div>`;}catch(e){node.textContent=e.message;throw e;}return;}
 if(f.id==='med-form'){clean(o);const id=o.id;delete o.id;await request(id?`/medicines/${id}`:`/patients/${pid}/medicines`,{method:id?'PATCH':'POST',json:o});S.modal='';await reload();return;}
 if(f.id==='vaccine-form'){clean(o);const id=o.id;delete o.id;if('duplicate_confirmed' in o)o.duplicate_confirmed=fd.has('duplicate_confirmed');await request(id?`/vaccines/${id}`:`/patients/${pid}/vaccines`,{method:id?'PATCH':'POST',json:id?{...o,confirmed:false}:o});S.modal='';await reload();return;}
 if(f.id==='lab-form'){clean(o);o.verified=fd.has('verified');await request(`/patients/${pid}/observations`,{method:'POST',json:o});S.modal='';return reload();}
 if(f.id==='med-event-form'){clean(o);const id=o.id;delete o.id;o.idempotency_key=crypto.randomUUID();await request(`/medicines/${id}/events`,{method:'POST',json:o});S.modal='';return reload();}
 const simple={'growth-form':'growth','admission-form':'admissions','episode-form':'episodes'};
 if(simple[f.id]){clean(o);if(f.id==='episode-form'){o.links=[];for(const k of ['medicine','observation'])if(o[k+'_link'])o.links.push({kind:k,id:Number(o[k+'_link'])});delete o.medicine_link;delete o.observation_link;}await request(`/patients/${pid}/${simple[f.id]}`,{method:'POST',json:o});S.modal='';return reload();}
 if(f.id==='administration-form'){clean(o);const id=o.visit_id;delete o.visit_id;o.checked_administration_record=fd.has('checked_administration_record');o.idempotency_key=crypto.randomUUID();await request(`/hospital-visits/${id}/administrations`,{method:'POST',json:o});S.modal='';return reload();}
 if(f.id==='reschedule-form'){clean(o);const id=o.id;delete o.id;o.checked_against_source=fd.has('checked_against_source');await request(`/hospital-visits/${id}/reschedule`,{method:'POST',json:o});S.modal='';return reload();}
 if(f.id==='series-form'){clean(o);const visits=[];for(let i=0;i<Number(o.count);i++){const d=new Date(o.planned_at);d.setDate(d.getDate()+i);const date=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);visits.push({facility:o.facility,purpose:o.purpose,planned_at:date,source_document_id:o.source_document_id,admission_id:o.admission_id,confirmed:true});}await request(`/patients/${pid}/hospital-visit-series`,{method:'POST',json:{visits,checked_against_hospital_plan:fd.has('checked')}});S.modal='';return reload();}
 if(f.id==='stop-form'){clean(o);const id=o.id;delete o.id;await request(`/medicines/${id}/stop`,{method:'POST',json:o});S.modal='';return reload();}
 if(f.id==='profile-form'){await request(`/patients/${pid}`,{method:'PATCH',json:o});return load();}
 if(f.id==='invite-form'){const r=await request(`/patients/${pid}/invitations`,{method:'POST',json:{...o,guardian_permission:fd.has('guardian_permission')}});el('#invitation-result').innerHTML=`<p>Share this single-use code privately with ${esc(o.email)}. It expires in three days.</p><input class="searchbox" readonly value="${esc(r.invitation_code)}" aria-label="Invitation code"/>`;return;}
 if(f.id==='accept-form'){await request('/invitations/accept',{method:'POST',json:o});return load();}
 if(f.id==='delete-form'){await request('/account/delete',{method:'POST',json:o});sessionStorage.clear();S.token='';S.patients=[];S.pid=null;S.modal='';render();return;}
 return baseSubmit(f);
};
document.addEventListener('change',e=>{if(e.target.id==='destination'){S.tab=e.target.value;render();}if(e.target.id==='review-page')loadReviewPage();});
document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone')){e.preventDefault();e.target.closest('#dropzone').classList.add('dragging');}});
document.addEventListener('dragleave',e=>e.target.closest('#dropzone')?.classList.remove('dragging'));
document.addEventListener('drop',async e=>{if(!e.target.closest('#dropzone'))return;e.preventDefault();await openModal('upload');const input=el('[name=file]');input.files=e.dataTransfer.files;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&S.modal)closeModal();if(e.key==='Enter'&&e.target.id==='dropzone')openModal('upload');if(e.key==='Tab'&&S.modal){const nodes=[...document.querySelectorAll('.modal button,.modal input,.modal select,.modal textarea,.modal a')].filter(x=>!x.disabled&&x.offsetParent);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
document.documentElement.dataset.theme=localStorage.getItem('babycare_theme')||'light';
setInterval(()=>{if(S.token&&S.pid&&S.tab==='notifications')request(`/patients/${S.pid}/notifications`).then(n=>{S.notifications=n;render();}).catch(()=>{});},30000);

const baseChildView=childView;
childView=function(){return baseChildView().replace('<button class="btn ghost small" data-action="logout"', '<details><summary>Have a family invitation?</summary><form id="accept-form">'+field('Invitation code','invitation_code','text','',true)+'<button class="btn alt">Accept invitation</button></form></details><button class="btn ghost small" data-action="logout"');};
/* Review edits write through to S.review so any background re-render shows exactly what was typed (including fields
   the caregiver deliberately cleared). */
document.addEventListener('input',e=>{const f=e.target&&e.target.closest&&e.target.closest('#review-form');if(f&&S.review&&S.modal==='review'){try{Object.assign(S.review,collectReview());}catch(err){}}},true);
document.addEventListener('change',e=>{const f=e.target&&e.target.closest&&e.target.closest('#review-form');if(f&&S.review&&S.modal==='review'){try{Object.assign(S.review,collectReview());}catch(err){}}},true);
